static void Run(){if(AssetDatabase.LoadAssetAtPath<GameObject>(D+"/Stack House Illuminated 3D Signs.prefab"))throw new Exception("Signs already built; no duplicate run");Directory.CreateDirectory(D);Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeCafe3DSigns");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeCafe3DSigns/Scene.unity",true);var filters=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).ToArray();var cafe=filters.Single(f=>f.name=="Plane.003_0");var billboard=filters.Single(f=>f.name=="billboard (68)");var mat=cafe.GetComponent<Renderer>().sharedMaterial;if(ShaderUtil.ShaderHasError(mat.shader))throw new Exception("Cafe shader error");atlas=new Texture2D(2,2);atlas.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(mat.GetTexture("_BaseMap"))));var cd=Read(cafe.sharedMesh);var cp=Field<Vector3[]>(cd,"p");var cu=Field<Vector2[][]>(cd,"uv");var ci=Field<int[]>(cd,"ids");var logo=new HashSet<int>();var logoWorld=new List<Vector3>();for(int i=0;i<ci.Length;i+=3){var uv=(cu[0][ci[i]]+cu[0][ci[i+1]]+cu[0][ci[i+2]])/3;if(uv.x>.135f&&uv.x<.30f&&uv.y>.08f&&uv.y<.245f){var a=cafe.transform.TransformPoint(cp[ci[i]]);var b=cafe.transform.TransformPoint(cp[ci[i+1]]);var c=cafe.transform.TransformPoint(cp[ci[i+2]]);if(Vector3.Cross(b-a,c-a).normalized.z>.9f){foreach(int v in new[]{ci[i],ci[i+1],ci[i+2]}){logo.Add(v);logoWorld.Add(cafe.transform.TransformPoint(cp[v]));}}}}if(logo.Count<4)throw new Exception("Old front logo not located");var center=logoWorld.Aggregate(Vector3.zero,(a,b)=>a+b)/logoWorld.Count;var changed=Copy(cd,"Cafe facade old logo replaced with atlas wood");var uvCopy=cu[0].ToArray();foreach(int v in logo){var w=cafe.transform.TransformPoint(cp[v]);uvCopy[v]=new Vector2(.36f+(w.x-center.x)*.018f,.585f+(w.y-center.y)*.018f);}for(int channel=2;channel<8;channel++){var full=new List<Vector4>();cafe.sha