var near=new G();var far=new G();Badge(near,true);Badge(far,false);var nm=near.Save("Stack House raised atlas logo near");var fm=far.Save("Stack House volumetric badge far");var master=new GameObject("Stack House Illuminated 3D Signs");foreach(int k in new[]{0,1}){var g=new GameObject(k==0?"Large rooftop Stack House logo":"Stack House logo on existing placed billboard");g.transform.SetParent(master.transform,false);g.transform.position=k==0?new Vector3(center.x,cafe.GetComponent<Renderer>().bounds.max.y+3.1f,center.z+.12f):new Vector3(bounds.center.x,cutoff+2.85f,bounds.center.z);g.transform.rotation=k==0?Quaternion.identity:Quaternion.LookRotation(front,Vector3.up);var nr=Add(g,"Raised lettering illuminated atlas badge",nm,mat);var fr=Add(g,"Far logo and luminous surround",fm,mat);var lod=g.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.09f,new[]{nr}),new LOD(.003f,new[]{fr})});lod.RecalculateBounds();}PrefabUtility.SaveAsPrefabAssetAndConnect(master,D+"/Stack House Illuminated 3D Signs.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);UnityEngine.Object.DestroyImmediate(atlas);typeof(FinalPNGCityDetails).GetMethod("Capture",F).Invoke(null,new object[]{scene,new Vector3(446.09f,37.85f,197.75f),new Vector3(439,33,155.8f),"Stack-House-3D-Signs-Day"});File.WriteAllText("FinalEnvironmentRoadReview/StackHouse3DSigns.txt","SUCCESS two large volumetric signs with raised atlas lettering and emissive surround; same Cafe01 atlas and original parking-cafe material; no new textures/materials/realtime lights. Existing billboard position/rotation/pole/platform preserved, original upper advertising head removed. Old cafe front logo remapped to existing wood; cafe/parking geometry otherwise unchanged. Near triangles="+nm.triangles.Length/3+" far="+fm.triangles.Length/3+" LODs saved scene/prefab. Billboard front="+front+" cutoff="+cutoff+" cafe sign center="+center);}
